document.querySelectorAll('a[href^="#"]').forEach(a=>a.addEventListener('click',e=>{const t=document.querySelector(a.getAttribute('href'));if(t){e.preventDefault();t.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})}}));
const roleHeading=[...document.querySelectorAll('.role h2')].find(h=>h.textContent.includes('Implementation Engineer I'));if(roleHeading)roleHeading.innerHTML='<span style="white-space:nowrap">Implementation Engineer I</span><br><em>(Software Systems)</em>';
const about=document.querySelector('.profile'),education=document.querySelector('.education');if(about&&education){about.querySelector('.section-label').textContent='About Me';const educationCard=document.createElement('div');educationCard.className='about-education';educationCard.innerHTML='<p class="tag">EDUCATION + ACHIEVEMENTS</p><h3>B.Tech in Computer Science &amp; Design Engineering</h3><p>Rajiv Gandhi Institute of Petroleum Technology · 2022–2026 · CGPA 7.42</p><div><span>600+ DSA problems solved on LeetCode</span><span>JEE Advanced 2022 · approximately top 2.5% nationwide</span></div>';about.querySelector('.profile-cards').after(educationCard);education.remove();const styles=document.createElement('style');styles.textContent='.about-education{margin-top:1px;border:1px solid var(--line);padding:25px}.about-education h3{font-size:20px;margin:12px 0 6px}.about-education>p:not(.tag){color:var(--muted);font-size:13px}.about-education>div{display:flex;gap:8px;flex-wrap:wrap;margin-top:18px}.about-education span{font:10px var(--mono);color:#c6ced9;border:1px solid #35404d;padding:9px}@media(max-width:800px){.about-education{padding:20px}}';document.head.append(styles)}
